INSERT INTO m253_art VALUES
(0,0,$m253$الديباجة$m253$,$m253$قانون رقم 136 لسنة 1981
فى شأن بعض الأحكام الخاصة بتأجير وبيع الأماكن وتنظيم العلاقة بين المؤجر والمستأجر
باسم الشعب
رئيس الجمهورية
قرر مجلس الشعب القانون الآتى نصه ، وقد أصدرناه :$m253$,'6eb5e1af3e48bc1baed61f098c86d595'),
(1,0,$m253$المادة 1$m253$,$m253$فيما عدا الإسكان الفاخر ، لا يجوز أن تزيد الأجرة السنوية للأماكن المرخص فى إقامتها لأغراض السكنى اعتبارا من تاريخ العمل بأحكام هذا القانون على 7٪ من قيمة الأرض والمبانى وعلى ألا تقل المساحة المؤجرة لهذه الأغراض عن ثلثى مساحة مبانى العقار .
ولا تسرى على هذه الأماكن أحكام المادة ( 13 ) عدا الفقرة الأخيرة منها والمادة ( 14 ) والفقرة الأولى من المادة ( 15 ) والفقرة الثانية من المادة ( 68 ) من القانون رقم 49 لسنة 1977 فى شأن تأجير وبيع الأماكن وتنظيم العلاقة بين المؤجر والمستأجر .
ويصدر بتحديد مواصفات الإسكان الفاخر قرار من الوزير المختص بالإسكان .$m253$,'32d71b317ef228b7ce687ff3bbcd22d2'),
(2,0,$m253$المادة 2$m253$,$m253$تقدر قيمة الأرض بالنسبة إلى الأماكن المنصوص عليها فى الفقرة الأولى من المادة السابقة وفقا لثمن المثل عند الترخيص بالبناء ، وتقدر قيمة المبانى وفقا للتكلفة الفعلية وقت البناء ، فإذا ثبت تراخى المالك عمدا عن إعداد المبنى للاستغلال ، تقدر تكلفة المبانى وفقا للأسعار التى كانت سائدة فى الوقت الذى كان مقدرا لإنهاء أعمال البناء وذلك دون إخلال بحق المحافظة المختصة فى استكمال الأعمال وفقا للقواعد المنظمة لذلك .
ويصدر قرار من الوزير المختص بالإسكان بتحديد الضوابط والمعايير التى تتبع فى تقدير قيمة الأرض والمبانى بما يكفل تقديرها بقيمتها الفعلية ويتضمن القرار كيفية تحديد الأجرة الإجمالية للمبنى وتوزيعها على وحداته ، وفقا لموقع كل وحدة وصقعها والانتفاع بها ومستوى البناء .$m253$,'eb9af3722091ae88d8326641ff2c955b'),
(3,0,$m253$المادة 3$m253$,$m253$تشكل بقرار من المحافظ المختص فى كل محافظة لجنة أو أكثر تضم بعض ذوى الخبرة لإعداد تقارير سنوية بناء على الدراسات التى تجريها فى نطاق المحافظة عن :
( أ ) ثمن المثل للأرض من واقع أسعار التعامل بالمدينة أو الحى أو المنطقة مستخلصة من كافة التصرفات والتعاملات القانونية سواء بين الأفراد أو الجهات الحكومية أو العامة أو الخاصة .
( ب ) أسعار التكلفة الفعلية لمختلف مستويات المبانى من واقع تطورات أسعار مواد البناء ونفقات العمالة ونتائج المناقصات وغيرها من الوسائل القانونية المتبعة لتنفيذ الأعمال .
ويؤخذ فى الاعتبار بالتقديرات الواردة فى هذه التقارير عند تحديد الأجرة وفقا لأحكام هذا القانون .
وتسلم المحافظة نسخة من هذه التقارير لكل من يطلبها فى مقابل رسم يصدر بتحديده قرار من المحافظ المختص بما لا يجاوز خمسة جنيهات للنسخة .$m253$,'88ccfc4d4fc08c8ed927295fa7eb7cda'),
(4,0,$m253$المادة 4$m253$,$m253$يتولى مالك المبنى تحديد الأجرة وفقا للضوابط والمعايير والتقارير والدراسات المنصوص عليها فى المواد السابقة ويتضمن عقد الإيجار مقدار الأجرة المحددة على هذه الأسس .
فإذا أبرم عقد الإيجار قبل إتمام البناء ، وحدد فيه الأجرة بصفة مبدئية ، كان على مالك المبنى إخطار المستأجر بالأجرة المحددة للمكان وفقا لأحكام هذا القانون وذلك خلال ثلاثين يوما من تاريخ إتمام البناء ، وبشرط ألا تجاوز الأجرة المبدئية إلا بمقدار الخمس .
وعلى المالك أن يمكن المستأجر من الاطلاع على المستندات اللازمة لتحديد الأجرة وذلك خلال شهر من تاريخ التعاقد أو من تاريخ الإخطار ، بحسب الأحوال .$m253$,'8c79590a37c771936dbd9c4dc7ecf202'),
(5,0,$m253$المادة 5$m253$,$m253$إذا رأى المستأجر أن الأجرة التى حددها المالك تزيد على الحدود المنصوص عليها فى هذا القانون جاز له خلال تسعين يوما من تاريخ التعاقد أو من تاريخ الإخطار أو من تاريخ شغله للمكان ، أن يطلب من لجنة تحديد الأجرة المختصة القيام بتحديد أجرة المكان وفقا للأسس المنصوص عليها فى هذا القانون .
ويكون الطعن على قرارات هذه اللجان أمام المحكمة الابتدائية التى يقع فى دائرتها المكان المؤجر ، وذلك خلال ستين يوما من تاريخ إخطار ذوى الشأن بقرارها ،
ولا تسرى على هذه الطعون أحكام المادتين 18 ، 20 من القانون 49 لسنة 1977$m253$,'868a45974b6ca2fe0898911c44b04ef0'),
(6,0,$m253$المادة 6$m253$,$m253$يجوز لمالك المبنى المنشأ اعتبارا من تاريخ العمل بهذا القانون أن يتقاضى من المستأجر مقدم إيجار لا يجاوز أجرة سنتين وذلك بالشروط الآتية :
1 - أن تكون الأعمال الأساسية للبناء قد تمت ولم يتبق إلا مرحلة التشطيب .
2 - أن يتم الاتفاق كتابة على مقدار مقدم الإيجار ، وكيفية خصمه من الأجرة المستحقة فى مدة لا تجاوز ضعف المدة المدفوع عنها المقدم وموعد إتمام البناء وتسليم الوحدة صالحة للاستعمال .
ويصدر قرار من الوزير المختص بالإسكان بتنظيم تقاضى مقدم الإيجار والحد الأقصى لمقدار المقدم بالنسبة لكل مستوى من مستويات البناء .
ولا يسرى حكم الفقرة الأخيرة من المادة ( 26 ) من القانون رقم 49 لسنة 1977 على مقدم الإيجار الذى يتقاضاه المالك وفقا لأحكام هذه المادة .$m253$,'cbf2ddfdcb57ceb4c77b81cffb93fbbf'),
(7,0,$m253$المادة 7$m253$,$m253$اعتبارا من تاريخ العمل بهذا القانون ، تزاد فى أول يناير من كل سنة أجرة الأماكن المؤجرة لغير أغراض السكنى المنشأة حتى 9 سبتمبر 1977 زيادة دورية ثابتة بواقع نسبة من القيمة الإيجارية المتخذة أساسا لحساب الضريبة على العقارات المبنية فى ذات وقت الإنشاء حتى لو أدخلت عليها تعديلات جوهرية .
ويخصص المالك نصف هذه الزيادة لمواجهة تكاليف الترميم والصيانة ويعتبر بمثابة أمانة تحت يده ، ويصدر قرار من الوزير المختص بالإسكان بتنظيم التصرف فيه لهذا الغرض .
وتحدد الزيادة المشار إليها وفقا للنسب الآتية :
( أ ) 30٪ عن الأماكن المنشأة قبل أول يناير سنة 1944 .
( ب ) 20٪ عن الأماكن المنشأة منذ أول يناير سنة 1944 ، وقبل 5 من نوفمبر سنة 1961 .
( ج ) 10٪ عن الأماكن المنشأة منذ 5 من نوفمبر سنة 1961 ، وحتى 6 من أكتوبر سنة 1973 .
( د ) 5٪ عن الأماكن المنشأة منذ 7 أكتوبر سنة 1973 ، وحتى 9 سبتمبر سنة 1977 .$m253$,'34936f35a5294fcf4cdc20beb574cced'),
(8,0,$m253$المادة 8$m253$,$m253$تؤدى الزيادة المنصوص عليها فى المادة السابقة فى ذات المواعيد المحددة لسداد الأجرة الأصلية ، ويترتب على عدم سداد هذه الزيادة ما يترتب على عدم سداد الأجرة من آثار .
وتقف هذه الزيادة عند انقضاء خمس سنوات كاملة على تاريخ استحقاق أول زيادة .$m253$,'cd2fc4b801fdd71f99dc65ce44471070'),
(9,0,$m253$المادة 9$m253$,$m253$تكون أعباء الترميم والصيانة الدورية والعامة للمبانى وما بها من مصاعد على الوجه الآتى :
1 - إذا كانت نصف حصيلة الزيادة المنصوص عليها فى المادة ( 7 ) كافية يتم الترميم والصيانة منها .
2 - إذا لم تف هذه الحصيلة أو إذا كان المبنى لا يحتوى على وحدات غير سكنية تستكمل أو توزع أعباء الترميم والصيانة بحسب الأحوال كما يلى :
( أ ) بالنسبة للمبانى المنشأة حتى 22 مارس سنة 1965 تكون بواقع الثلث على الملاك والثلثين على شاغلى المبنى .
( ب ) بالنسبة للمبانى المنشأة بعد 22 مارس سنة 1965 وحتى سبتمبر سنة 1977 تكون مناصفة بين الملاك وشاغلى المبنى .
( ج ) بالنسبة للمبانى المنشأة أو التى تنشأ بعد 9 سبتمبر سنة 1977 تكون بواقع الثلثين على الملاك والثلث على شاغلى المبنى .
وإذا لم يتم الاتفاق على توزيع تكاليف الترميم والصيانة فيما بين الملاك والشاغلين أو الشاغلين فيما بينهم ، يجوز لأى منهم الالتجاء إلى قاضى الأمور المستعجلة لتوزيع هذه التكاليف بين الملاك وبين الشاغلين وتحديد نصيب كل شاغل .
ومع ذلك تكون أعباء الترميم والصيانة على عاتق الملاك وذلك خلال العشر سنوات المنصوص عليها فى المادة 651 من القانون المدنى .
وفيما عدا ما ورد فيه نص بهذه المادة يستمر العمل بالأحكام المنظمة للترميم والصيانة فى كل من أحكام القانون رقم 78 لسنة 1974 فى شأن المصاعد الكهربائية والقانون رقم 49 لسنة 1977 .
أما الأعمال التى لا تسرى عليها أحكام الترميم والصيانة والتى يقصد بها تحسين الأجزاء المشتركة للمبنى أو زيادة الانتفاع بها فتكون بالاتفاق بين الملاك والشاغلين .
ومع عدم الإخلال بعلاقة العمل بين المالك وحارس المبنى ، يوزع الحد الأدنى المقرر قانونا لأجر الحارس وفقا للبنود أ ، ب ، ج من هذه المادة .
وتلغى المادة ( 61 ) من القانون رقم 49 لسنة 1977 والمادة 13 من القانون رقم 78 لسنة 1974 ، وذلك اعتبارا من تاريخ العمل بهذا القانون .$m253$,'8b553d9bcfcf4b88564082e0e097cbbf'),
(10,0,$m253$المادة 10$m253$,$m253$تكفل الدولة تقديم قروض تعاونية ميسرة لترميم وصيانة المبانى ويكون للقرض وملحقاته امتياز عام على أموال المدين ضمانا للسداد وتكون مرتبة هذا الامتياز تالية للضرائب والرسوم .
وتعفى القروض من جميع الضرائب والرسوم وتحصل بطريق الحجز الإدارى .
وتلغى أحكام المادة ( 62 ) من القانون رقم 49 لسنة 1977 وذلك اعتبارا من تاريخ العمل بهذا القانون .$m253$,'1c68699bbd3d424894f091a73f5f6bcb'),
(11,0,$m253$المادة 11$m253$,$m253$فيما عدا المبانى من المستوى الفاخر يعفى اعتبارا من أول يناير التالى لتاريخ العمل بهذا القانون مالكو وشاغلو المبانى المؤجرة لأغراض السكنى التى أنشئت أو تنشأ اعتبارا من 9 سبتمبر سنة 1977 من جميع الضرائب العقارية الأصلية والإضافية ولا تدخل إيرادات هذه المساكن فى وعاء الضريبة العامة على الإيراد .
ولا يسرى حكم الفقرتين السابقتين على الأماكن المستعملة مفروشة أو فنادق أو بنسيونات$m253$,'6e561fd2480a951d1f635c8828087bba'),
(12,0,$m253$المادة 12$m253$,$m253$فيما عدا المبانى من المستوى الفاخر يلغى شرط الحصول على موافقة لجنة توجيه وتنظيم أعمال البناء قبل الحصول على الترخيص بإقامة المبانى وسائر أحكام الباب الأول من القانون رقم 106 لسنة 1976 فى شأن توجيه وتنظيم أعمال البناء ، كما تلغى المادة 21 من ذلك القانون .$m253$,'57ebf8e67031beef0bcd58aa78cec439'),
(13,0,$m253$المادة 13$m253$,$m253$يحظر على الملاك من الأفراد وشركات الأشخاص أن يعرضوا للتمليك للغير أو التأجير المفروش فى كل مبنى مكون من أكثر من وحدة واحدة يرخص فى إقامته أو يبدأ فى إنشائه من تاريخ العمل بهذا القانون ما يزيد على ثلث مجموع مساحة وحدات المبنى وذلك دون إخلال بنسبة الثلثين المخصصة للتأجير لأغراض السكنى وفقا لأحكام الفقرة الأولى من المادة الأولى .
ويسرى هذا القيد ولو تعدد الملاك مع مراعاة نسبة ما يملكه كل منهم وبحد أدنى وحدة واحدة لكل مالك .
ويمتنع على مصلحة الشهر العقارى والتوثيق شهر المحررات المتعلقة بهذه الوحدات ما لم يقدم صاحب الشأن ما يثبت التزامه بتطبيق أحكام هذه المادة .
ويقع باطلا كل تصرف يخالف ذلك لو كان مسجلا .
وبعد تأجير النسبة المقررة طبقا لهذه المادة يجوز للمالك التصرف فى هذه النسبة كلها أو بعضها وفقا للقواعد العامة .
وفى حالة بيع كامل العقار يلتزم المشترى بأحكام هذه المادة .$m253$,'a2c53a1db02fc792f6ef261c56baf4c5'),
(14,0,$m253$المادة 14$m253$,$m253$يخصص ثلثا نسبة الـ 15٪ المخصصة للخدمات من أرباح شركات القطاع العام لتمويل الوحدات اللازمة لإسكان العاملين بكل شركة أو مجموعة من الشركات المتجاورة ، ويؤول ما يفيض عن حاجة هؤلاء العاملين إلى صندوق تمويل الإسكان الاقتصادى بالمحافظة .$m253$,'9cb931ff1b1653cff58b1e84c51073bb'),
(15,0,$m253$المادة 15$m253$,$m253$تكفل الدولة دعم النشاط التعاونى الإسكانى وتوفير ما يلزم له من قروض ومواد للبناء وفقا لأحكام التشريعات المنظمة لهذا النشاط .
كما يكون للأفراد عند تعلية مبانيهم أو استكمالها أو التوسع فيها كما يكون للراغبين فى الاستثمار فى مختلف مستويات الإسكان عدا الفاخر منها ، الحصول على القروض الميسرة التى تقدمها الدولة والهيئات العامة والجهاز المصرفى .
وكل ذلك وفقا للضوابط التى يصدرها قرار من الوزير المختص بالإسكان .$m253$,'52275014c1007f4517b693d09e173da6'),
(16,0,$m253$المادة 16$m253$,$m253$يحق لمستأجرى المدارس والأقسام الداخلية لإيواء الدارسين بها والمستشفيات وملحقاتهما فى حالة تأجيرها لهم مفروشة الاستمرار فى العين ولو انتهت المدة المتفق عليها وذلك بالشروط وبالأجرة المنصوص عليها فى العقد .$m253$,'5cccff659d52e418d9c2cb76aeb7e28d'),
(17,0,$m253$المادة 17$m253$,$m253$تنتهى بقوة القانون عقود التأجير لغير المصريين بانتهاء المدد المحددة قانونا لإقامتهم بالبلاد .
بالنسبة للأماكن التى يستأجرها غير المصريين فى تاريخ العمل بأحكام هذا القانون يجوز للمؤجر أن يطلب إخلاءها إذا ما انتهت إقامة المستأجر غير المصرى فى البلاد .
وتثبت إقامة غير المصرى بشهادة من الجهة الإدارية المختصة ويكون إعلان غير المصرى الذى انتهت إقامته قانونا عن طريق النيابة العامة .
ومع ذلك يستمر عقد الإيجار بقوة القانون فى جميع الأحوال لصالح الزوجة المصرية ولأولادها منه الذين كانوا يقيمون بالعين المؤجرة ما لم يثبت مغادرتهم البلاد نهائيا .$m253$,'eb4e78389d78f5f63c28d86f0e13ef0d'),
(18,0,$m253$المادة 18$m253$,$m253$لا يجوز للمؤجر أن يطلب إخلاء المكان ولو انتهت المدة المتفق عليها فى العقد إلا لأحد الأسباب الآتية :
( أ ) الهدم الكلى أو الجزئى للمنشآت الآيلة للسقوط والإخلاء المؤقت لمقتضيات الترميم والصيانة وفقا للأحكام المنظمة لذلك بالقوانين السارية .
( ب ) إذا لم يقم المستأجر بالوفاء بالأجرة المستحقة خلال خمسة عشر يوما من تاريخ تكليفه بذلك بكتاب موصى عليه مصحوب بعلم الوصول دون مظروف أو بإعلان على يد محضر ولا يحكم بالإخلاء إذا قام المستأجر قبل إقفال باب المرافعة فى الدعوى بأداء الأجرة وكافة ما تكبده المؤجر من مصاريف ونفقات فعلية ،
ولا ينفذ حكم القضاء المستعجل بطرد المستأجر من العين بسبب التأخير فى سداد الأجرة إعمالا للشرط الفاسخ الصريح إذا ما سدد المستأجر الأجرة والمصاريف والأتعاب عند تنفيذ الحكم وبشرط أن يتم التنفيذ فى مواجهة المستأجر .
فإذا تكرر امتناع المستأجر أو تأخره فى الوفاء بالأجرة المستحقة دون مبررات تقدرها المحكمة حكم عليه بالإخلاء أو الطرد بحسب الأحوال .
( ج ) إذا ثبت أن المستأجر قد تنازل عن المكان المؤجر ، أو أجره من الباطن بغير إذن كتابى صريح من المالك للمستأجر الأصلى ، أو تركه للغير بقصد الاستغناء عنه نهائيا وذلك دون إخلال بالحالات التى يجيز فيها القانون للمستأجر تأجير المكان مفروشا أو التنازل عنه أو تأجيره من الباطن أو تركه لذوى القربى وفقا لأحكام المادة 29 من القانون 49 لسنة 1977
( د ) إذا ثبت بحكم قضائى نهائى أن المستأجر استعمل المكان المؤجر أو سمح باستعماله بطريقة مقلقة للراحة أو ضارة بسلامة المبنى أو بالصحة العامة أو فى أغراض منافية للآداب العامة .
ومع عدم الإخلال بالأسباب المشار إليها لا تمتد بقوة القانون عقود إيجار الأماكن المفروشة .
وتلغى المادة ( 31 ) من القانون رقم 49 لسنة 1977 وذلك اعتبارا من تاريخ العمل بهذا القانون .$m253$,'2563042dd2ba785aafd84e69e5fe8ce7'),
(19,0,$m253$المادة 19$m253$,$m253$فى الأحوال التى يتم فيها تغيير استعمال العين إلى غير أغراض السكنى تزاد الأجرة القانونية بنسبة :
( 1 ) 200٪ للمبانى المنشأة قبل أول يناير 1944 .
( 2 ) 100٪ للمبانى المنشأة منذ أول يناير 1944 وقبل 5 نوفمبر 1961
( 3 ) 75٪ للمبانى المنشأة منذ 5 نوفمبر 1961 وحتى 9 سبتمبر 1977 .
( 4 ) 50٪ للمبانى المنشأة أو التى تنشأ بعد 9 سبتمبر 1977 .
وفى حالة التغيير الجزئى للاستعمال يستحق المالك نصف النسب المشار إليها .
ويشترط ألا يترتب على تغيير الاستعمال كليا أو جزئيا إضرار بالمبنى أو بشاغليه .
وتلغى المادة ( 23 ) من القانون رقم 49 لسنة 1977 وذلك اعتبارا من تاريخ العمل بهذا القانون .$m253$,'a1307b945e5459cf3e494daa3f78034c'),
(20,0,$m253$المادة 20$m253$,$m253$يحق للمالك عند قيام المستأجر فى الحالات التى يجوز لهم فيها بيع المتجر أو المصنع أو التنازل عن حق الانتفاع بالوحدة السكنية أو المؤجرة لغير أغراض السكنى الحصول على 50٪ من ثمن البيع أو مقابل التنازل بحسب الأحوال ، بعد خصم قيمة المنقولات التى بالعين .
وعلى المستأجر قبل إبرام الاتفاق إعلان المالك على يد محضر بالثمن المعروض ويكون للمالك الحق فى الشراء إذا أبدى رغبته فى ذلك وأودع الثمن مخصوما منه نسبة الـ 50٪ المشار إليها خزانة المحكمة الجزئية الواقع فى دائرتها العقار إيداعا مشروطا بالتنازل عن عقد الإيجار وتسليم العين وذلك خلال شهر من تاريخ الإعلان .
وبانقضاء ذلك الأجل يجوز للمستأجر أن يبيع لغير المالك مع التزام المشترى بأن يؤدى للمالك مباشرة نسبة الـ 50٪ المشار إليها .$m253$,'f3655a35bde8459a25f289f19e0ba2c2'),
(21,0,$m253$المادة 21$m253$,$m253$يشترط ألا يزيد مجموع ما يقوم المستأجر هو وزوجه وأولاده القصر غير المتزوجين بتأجيره مفروشا - بغير موافقة المالك - على شقة واحدة فى نفس المدينة .
ويمتد فى تحديد المدينة بأحكام قانون الحكم المحلى .$m253$,'09819408b5d7d8d90296ba221849023b'),
(22,0,$m253$المادة 22$m253$,$m253$تعطى أولوية فى تأجير الوحدات السكنية التى تقيمها الدولة أو المحافظات أو الهيئات العامة أو شركات القطاع العام لتلبية احتياجات العاملين الذين انتهت خدمتهم من شاغلى المساكن التابعة للحكومة ووحدات الحكم المحلى والهيئات العامة وشركات القطاع العام وكذلك ملاك العقارات وأقاربهم حتى الدرجة الثانية فى المحافظة التى يؤجرون بها وحدات العقار المملوك لهم للغير ، وتوزع هذه الوحدات بينهم وفقا للأولويات التى يصدر بها قرار من المحافظ المختص .
وإذا أقام المستأجر مبنى مملوكا له يتكون من أكثر من ثلاث وحدات فى تاريخ لاحق لاستئجاره يكون بالخيار بين الاحتفاظ بسكنه الذى يستأجره أو توفير مكان ملائم لمالكه أو أحد أقاربه حتى الدرجة الثانية بالمبنى الذى أقامه بما لا يجاوز مثلى الأجرة المستحقة له عن الوحدة التى يستأجرها منه .$m253$,'fb55e6dabe3c223e819fc19738d620a8'),
(23,0,$m253$المادة 23$m253$,$m253$يعاقب بعقوبة جريمة النصب المنصوص عليها فى قانون العقوبات المالك الذى يتقاضى بأية صورة من الصور ، بذاته أو بالوساطة ، أكثر من مقدم عن ذات الوحدة أو يؤجرها لأكثر من مستأجر ، أو يبيعها لغير من تعاقد معه على شرائها ، ويبطل كل تصرف بالبيع لاحق لهذا التاريخ ولو كان مسجلا .
ويعاقب بذات العقوبة المالك الذى يتخلف دون مقتض عن تسليم الوحدة فى الموعد المحدد فضلا عن الزامه بأن يؤدى إلى الطرف الآخر مثلى مقدار المقدم وذلك دون إخلال بالتعاقد ويحق للمستأجر فى استكمال الأعمال الناقصة وفقا لحكم الفقرة الأخيرة من المادة 13 من القانون رقم 49 لسنة 1977 .
ويكون ممثل الشخص الاعتبارى مسئولا عما يقع منه من مخالفات لأحكام هذه المادة .$m253$,'395feab9e5673dddb7288e0aafca2873'),
(24,0,$m253$المادة 24$m253$,$m253$فيما عدا العقوبة المقررة لجريمة خلو الرجل تلغى جميع العقوبات المقيدة للحرية المنصوص عليها فى القوانين المنظمة لتأجير الأماكن وتنظيم العلاقة بين المؤجر والمستأجر ذلك دون إخلال بأحكام المادة السابقة .
ومع ذلك يعفى من جميع العقوبات المقررة لجريمة خلو الرجل كل من بادر إلى رد ما تقاضاه بالمخالفة لأحكام القانون إلى صاحب الشأن ، وأداء مثليه إلى صندوق تمويل الإسكان الاقتصادى بالمحافظة وذلك قبل أن يصبح الحكم نهائيا فى الدعوى .$m253$,'3ca388b05360ec3110c1b472422b6a5d'),
(25,0,$m253$المادة 25$m253$,$m253$يقع باطلا بطلانا مطلقا كل شرط أو تعاقد يتم بالمخالفة لأحكام هذا القانون أو القوانين السابقة له المنظمة للعلاقة بين المالك والمستأجر .
وفضلا عن الحكم بالغرامة المنصوص عليها فى هذه القوانين تقضى المحكمة المختصة بإبطال التصرف المخالف واعتباره كأن لم يكن ، ويرد الحالة إلى ما يتفق مع أحكام القانون مع إلزام المخالف بالتعويض إن كان له مقتض .
وفى جميع الأحوال يلزم كل من يحصل على مبالغ بالمخالفة لأحكام تلك القوانين بأن يردها إلى من أداها ، كما يلزم فضلا عن ذلك بدفع مثل هذه المبالغ لصندوق تمويل الإسكان الاقتصادى بالمحافظة .
ويثبت أداء هذه المبالغ بجميع طرق الإثبات .$m253$,'2ed18e4b94008b9051cbe871c40ecb01'),
(26,0,$m253$المادة 26$m253$,$m253$لا تسرى أحكام المادة ( 9 ) من هذا القانون على الأماكن التى تحتاج إلى ترميم وصيانة بسبب أضرار الحرب ، ويستمر العمل بالقواعد والنظم المطبقة حاليا فى شأن ترميمها وصيانتها .$m253$,'aaed5ddd1400dc94f195852168e3481d'),
(27,0,$m253$المادة 27$m253$,$m253$تعامل فى تطبيق أحكام هذا القانون معاملة المبانى المؤجرة لأغراض السكنى ، الأماكن المستعملة فى أغراض لا تدخل فى نطاق النشاط التجارى أو الصناعى أو المهنى الخاضع للضريبة على الأرباح التجارية والصناعية أو الضريبة على أرباح المهن غير التجارية .
ولا يفيد من أحكام هذه المادة سوى المستأجرين المصريين .$m253$,'9742d20105a6303a8cfd3019fc165f08'),
(28,0,$m253$المادة 28$m253$,$m253$تعامل صناديق التأمين الخاصة وصناديق الإسكان معاملة الجمعيات التعاونية لبناء المساكن ، وذلك بالنسبة لما تستثمره هذه الصناديق فى أموال من مجال الإسكان عدا المستوى الفاخر .$m253$,'eee27d7431e3ce90cbd94ddf4446e258'),
(29,0,$m253$المادة 29$m253$,$m253$ينشر هذا القانون فى الجريدة الرسمية ، ويعمل به من اليوم التالى لتاريخ نشره .$m253$,'ae1ca224d7e2797691b06d55d9fd8f82');

INSERT INTO m253_ver VALUES
(0,0,1,$m253$قانون رقم 136 لسنة 1981
فى شأن بعض الأحكام الخاصة بتأجير وبيع الأماكن وتنظيم العلاقة بين المؤجر والمستأجر
باسم الشعب
رئيس الجمهورية
قرر مجلس الشعب القانون الآتى نصه ، وقد أصدرناه :$m253$,'6eb5e1af3e48bc1baed61f098c86d595',DATE '1981-07-31',NULL,'active',NULL,NULL,$m253$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 31 تابع (ج) فى 30 يوليه 1981 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m253$),
(1,0,1,$m253$فيما عدا الإسكان الفاخر ، لا يجوز أن تزيد الأجرة السنوية للأماكن المرخص فى إقامتها لأغراض السكنى اعتبارا من تاريخ العمل بأحكام هذا القانون على 7٪ من قيمة الأرض والمبانى وعلى ألا تقل المساحة المؤجرة لهذه الأغراض عن ثلثى مساحة مبانى العقار .
ولا تسرى على هذه الأماكن أحكام المادة ( 13 ) عدا الفقرة الأخيرة منها والمادة ( 14 ) والفقرة الأولى من المادة ( 15 ) والفقرة الثانية من المادة ( 68 ) من القانون رقم 49 لسنة 1977 فى شأن تأجير وبيع الأماكن وتنظيم العلاقة بين المؤجر والمستأجر .
ويصدر بتحديد مواصفات الإسكان الفاخر قرار من الوزير المختص بالإسكان .$m253$,'32d71b317ef228b7ce687ff3bbcd22d2',DATE '1981-07-31',NULL,'active',NULL,NULL,$m253$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 31 تابع (ج) فى 30 يوليه 1981 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m253$),
(2,0,1,$m253$تقدر قيمة الأرض بالنسبة إلى الأماكن المنصوص عليها فى الفقرة الأولى من المادة السابقة وفقا لثمن المثل عند الترخيص بالبناء ، وتقدر قيمة المبانى وفقا للتكلفة الفعلية وقت البناء ، فإذا ثبت تراخى المالك عمدا عن إعداد المبنى للاستغلال ، تقدر تكلفة المبانى وفقا للأسعار التى كانت سائدة فى الوقت الذى كان مقدرا لإنهاء أعمال البناء وذلك دون إخلال بحق المحافظة المختصة فى استكمال الأعمال وفقا للقواعد المنظمة لذلك .
ويصدر قرار من الوزير المختص بالإسكان بتحديد الضوابط والمعايير التى تتبع فى تقدير قيمة الأرض والمبانى بما يكفل تقديرها بقيمتها الفعلية ويتضمن القرار كيفية تحديد الأجرة الإجمالية للمبنى وتوزيعها على وحداته ، وفقا لموقع كل وحدة وصقعها والانتفاع بها ومستوى البناء .$m253$,'eb9af3722091ae88d8326641ff2c955b',DATE '1981-07-31',NULL,'active',NULL,NULL,$m253$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 31 تابع (ج) فى 30 يوليه 1981 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m253$),
(3,0,1,$m253$تشكل بقرار من المحافظ المختص فى كل محافظة لجنة أو أكثر تضم بعض ذوى الخبرة لإعداد تقارير سنوية بناء على الدراسات التى تجريها فى نطاق المحافظة عن :
( أ ) ثمن المثل للأرض من واقع أسعار التعامل بالمدينة أو الحى أو المنطقة مستخلصة من كافة التصرفات والتعاملات القانونية سواء بين الأفراد أو الجهات الحكومية أو العامة أو الخاصة .
( ب ) أسعار التكلفة الفعلية لمختلف مستويات المبانى من واقع تطورات أسعار مواد البناء ونفقات العمالة ونتائج المناقصات وغيرها من الوسائل القانونية المتبعة لتنفيذ الأعمال .
ويؤخذ فى الاعتبار بالتقديرات الواردة فى هذه التقارير عند تحديد الأجرة وفقا لأحكام هذا القانون .
وتسلم المحافظة نسخة من هذه التقارير لكل من يطلبها فى مقابل رسم يصدر بتحديده قرار من المحافظ المختص بما لا يجاوز خمسة جنيهات للنسخة .$m253$,'88ccfc4d4fc08c8ed927295fa7eb7cda',DATE '1981-07-31',NULL,'active',NULL,NULL,$m253$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 31 تابع (ج) فى 30 يوليه 1981 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m253$),
(4,0,1,$m253$يتولى مالك المبنى تحديد الأجرة وفقا للضوابط والمعايير والتقارير والدراسات المنصوص عليها فى المواد السابقة ويتضمن عقد الإيجار مقدار الأجرة المحددة على هذه الأسس .
فإذا أبرم عقد الإيجار قبل إتمام البناء ، وحدد فيه الأجرة بصفة مبدئية ، كان على مالك المبنى إخطار المستأجر بالأجرة المحددة للمكان وفقا لأحكام هذا القانون وذلك خلال ثلاثين يوما من تاريخ إتمام البناء ، وبشرط ألا تجاوز الأجرة المبدئية إلا بمقدار الخمس .
وعلى المالك أن يمكن المستأجر من الاطلاع على المستندات اللازمة لتحديد الأجرة وذلك خلال شهر من تاريخ التعاقد أو من تاريخ الإخطار ، بحسب الأحوال .$m253$,'8c79590a37c771936dbd9c4dc7ecf202',DATE '1981-07-31',NULL,'active',NULL,NULL,$m253$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 31 تابع (ج) فى 30 يوليه 1981 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m253$),
(5,0,1,$m253$إذا رأى المستأجر أن الأجرة التى حددها المالك تزيد على الحدود المنصوص عليها فى هذا القانون جاز له خلال تسعين يوما من تاريخ التعاقد أو من تاريخ الإخطار أو من تاريخ شغله للمكان ، أن يطلب من لجنة تحديد الأجرة المختصة القيام بتحديد أجرة المكان وفقا للأسس المنصوص عليها فى هذا القانون .
ويكون الطعن على قرارات هذه اللجان أمام المحكمة الابتدائية التى يقع فى دائرتها المكان المؤجر ، وذلك خلال ستين يوما من تاريخ إخطار ذوى الشأن بقرارها ،
ولا تسرى على هذه الطعون أحكام المادتين 18 ، 20 من القانون 49 لسنة 1977$m253$,'868a45974b6ca2fe0898911c44b04ef0',DATE '1981-07-31',NULL,'active',NULL,NULL,$m253$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 31 تابع (ج) فى 30 يوليه 1981 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m253$),
(6,0,1,$m253$يجوز لمالك المبنى المنشأ اعتبارا من تاريخ العمل بهذا القانون أن يتقاضى من المستأجر مقدم إيجار لا يجاوز أجرة سنتين وذلك بالشروط الآتية :
1 - أن تكون الأعمال الأساسية للبناء قد تمت ولم يتبق إلا مرحلة التشطيب .
2 - أن يتم الاتفاق كتابة على مقدار مقدم الإيجار ، وكيفية خصمه من الأجرة المستحقة فى مدة لا تجاوز ضعف المدة المدفوع عنها المقدم وموعد إتمام البناء وتسليم الوحدة صالحة للاستعمال .
ويصدر قرار من الوزير المختص بالإسكان بتنظيم تقاضى مقدم الإيجار والحد الأقصى لمقدار المقدم بالنسبة لكل مستوى من مستويات البناء .
ولا يسرى حكم الفقرة الأخيرة من المادة ( 26 ) من القانون رقم 49 لسنة 1977 على مقدم الإيجار الذى يتقاضاه المالك وفقا لأحكام هذه المادة .$m253$,'cbf2ddfdcb57ceb4c77b81cffb93fbbf',DATE '1981-07-31',NULL,'active',NULL,NULL,$m253$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 31 تابع (ج) فى 30 يوليه 1981 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m253$),
(7,0,1,$m253$اعتبارا من تاريخ العمل بهذا القانون ، تزاد فى أول يناير من كل سنة أجرة الأماكن المؤجرة لغير أغراض السكنى المنشأة حتى 9 سبتمبر 1977 زيادة دورية ثابتة بواقع نسبة من القيمة الإيجارية المتخذة أساسا لحساب الضريبة على العقارات المبنية فى ذات وقت الإنشاء حتى لو أدخلت عليها تعديلات جوهرية .
ويخصص المالك نصف هذه الزيادة لمواجهة تكاليف الترميم والصيانة ويعتبر بمثابة أمانة تحت يده ، ويصدر قرار من الوزير المختص بالإسكان بتنظيم التصرف فيه لهذا الغرض .
وتحدد الزيادة المشار إليها وفقا للنسب الآتية :
( أ ) 30٪ عن الأماكن المنشأة قبل أول يناير سنة 1944 .
( ب ) 20٪ عن الأماكن المنشأة منذ أول يناير سنة 1944 ، وقبل 5 من نوفمبر سنة 1961 .
( ج ) 10٪ عن الأماكن المنشأة منذ 5 من نوفمبر سنة 1961 ، وحتى 6 من أكتوبر سنة 1973 .
( د ) 5٪ عن الأماكن المنشأة منذ 7 أكتوبر سنة 1973 ، وحتى 9 سبتمبر سنة 1977 .$m253$,'34936f35a5294fcf4cdc20beb574cced',DATE '1981-07-31',NULL,'active',NULL,NULL,$m253$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 31 تابع (ج) فى 30 يوليه 1981 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m253$),
(8,0,1,$m253$تؤدى الزيادة المنصوص عليها فى المادة السابقة فى ذات المواعيد المحددة لسداد الأجرة الأصلية ، ويترتب على عدم سداد هذه الزيادة ما يترتب على عدم سداد الأجرة من آثار .
وتقف هذه الزيادة عند انقضاء خمس سنوات كاملة على تاريخ استحقاق أول زيادة .$m253$,'cd2fc4b801fdd71f99dc65ce44471070',DATE '1981-07-31',NULL,'active',NULL,NULL,$m253$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 31 تابع (ج) فى 30 يوليه 1981 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m253$),
(9,0,1,$m253$تكون أعباء الترميم والصيانة الدورية والعامة للمبانى وما بها من مصاعد على الوجه الآتى :
1 - إذا كانت نصف حصيلة الزيادة المنصوص عليها فى المادة ( 7 ) كافية يتم الترميم والصيانة منها .
2 - إذا لم تف هذه الحصيلة أو إذا كان المبنى لا يحتوى على وحدات غير سكنية تستكمل أو توزع أعباء الترميم والصيانة بحسب الأحوال كما يلى :
( أ ) بالنسبة للمبانى المنشأة حتى 22 مارس سنة 1965 تكون بواقع الثلث على الملاك والثلثين على شاغلى المبنى .
( ب ) بالنسبة للمبانى المنشأة بعد 22 مارس سنة 1965 وحتى سبتمبر سنة 1977 تكون مناصفة بين الملاك وشاغلى المبنى .
( ج ) بالنسبة للمبانى المنشأة أو التى تنشأ بعد 9 سبتمبر سنة 1977 تكون بواقع الثلثين على الملاك والثلث على شاغلى المبنى .
وإذا لم يتم الاتفاق على توزيع تكاليف الترميم والصيانة فيما بين الملاك والشاغلين أو الشاغلين فيما بينهم ، يجوز لأى منهم الالتجاء إلى قاضى الأمور المستعجلة لتوزيع هذه التكاليف بين الملاك وبين الشاغلين وتحديد نصيب كل شاغل .
ومع ذلك تكون أعباء الترميم والصيانة على عاتق الملاك وذلك خلال العشر سنوات المنصوص عليها فى المادة 651 من القانون المدنى .
وفيما عدا ما ورد فيه نص بهذه المادة يستمر العمل بالأحكام المنظمة للترميم والصيانة فى كل من أحكام القانون رقم 78 لسنة 1974 فى شأن المصاعد الكهربائية والقانون رقم 49 لسنة 1977 .
أما الأعمال التى لا تسرى عليها أحكام الترميم والصيانة والتى يقصد بها تحسين الأجزاء المشتركة للمبنى أو زيادة الانتفاع بها فتكون بالاتفاق بين الملاك والشاغلين .
ومع عدم الإخلال بعلاقة العمل بين المالك وحارس المبنى ، يوزع الحد الأدنى المقرر قانونا لأجر الحارس وفقا للبنود أ ، ب ، ج من هذه المادة .
وتلغى المادة ( 61 ) من القانون رقم 49 لسنة 1977 والمادة 13 من القانون رقم 78 لسنة 1974 ، وذلك اعتبارا من تاريخ العمل بهذا القانون .$m253$,'8b553d9bcfcf4b88564082e0e097cbbf',DATE '1981-07-31',NULL,'active',NULL,NULL,$m253$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 31 تابع (ج) فى 30 يوليه 1981 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m253$),
(10,0,1,$m253$تكفل الدولة تقديم قروض تعاونية ميسرة لترميم وصيانة المبانى ويكون للقرض وملحقاته امتياز عام على أموال المدين ضمانا للسداد وتكون مرتبة هذا الامتياز تالية للضرائب والرسوم .
وتعفى القروض من جميع الضرائب والرسوم وتحصل بطريق الحجز الإدارى .
وتلغى أحكام المادة ( 62 ) من القانون رقم 49 لسنة 1977 وذلك اعتبارا من تاريخ العمل بهذا القانون .$m253$,'1c68699bbd3d424894f091a73f5f6bcb',DATE '1981-07-31',NULL,'active',NULL,NULL,$m253$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 31 تابع (ج) فى 30 يوليه 1981 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m253$),
(11,0,1,$m253$فيما عدا المبانى من المستوى الفاخر يعفى اعتبارا من أول يناير التالى لتاريخ العمل بهذا القانون مالكو وشاغلو المبانى المؤجرة لأغراض السكنى التى أنشئت أو تنشأ اعتبارا من 9 سبتمبر سنة 1977 من جميع الضرائب العقارية الأصلية والإضافية ولا تدخل إيرادات هذه المساكن فى وعاء الضريبة العامة على الإيراد .
ولا يسرى حكم الفقرتين السابقتين على الأماكن المستعملة مفروشة أو فنادق أو بنسيونات$m253$,'6e561fd2480a951d1f635c8828087bba',DATE '1981-07-31',NULL,'active',NULL,NULL,$m253$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 31 تابع (ج) فى 30 يوليه 1981 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m253$),
(12,0,1,$m253$فيما عدا المبانى من المستوى الفاخر يلغى شرط الحصول على موافقة لجنة توجيه وتنظيم أعمال البناء قبل الحصول على الترخيص بإقامة المبانى وسائر أحكام الباب الأول من القانون رقم 106 لسنة 1976 فى شأن توجيه وتنظيم أعمال البناء ، كما تلغى المادة 21 من ذلك القانون .$m253$,'57ebf8e67031beef0bcd58aa78cec439',DATE '1981-07-31',NULL,'active',NULL,NULL,$m253$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 31 تابع (ج) فى 30 يوليه 1981 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m253$),
(13,0,1,$m253$يحظر على الملاك من الأفراد وشركات الأشخاص أن يعرضوا للتمليك للغير أو التأجير المفروش فى كل مبنى مكون من أكثر من وحدة واحدة يرخص فى إقامته أو يبدأ فى إنشائه من تاريخ العمل بهذا القانون ما يزيد على ثلث مجموع مساحة وحدات المبنى وذلك دون إخلال بنسبة الثلثين المخصصة للتأجير لأغراض السكنى وفقا لأحكام الفقرة الأولى من المادة الأولى .
ويسرى هذا القيد ولو تعدد الملاك مع مراعاة نسبة ما يملكه كل منهم وبحد أدنى وحدة واحدة لكل مالك .
ويمتنع على مصلحة الشهر العقارى والتوثيق شهر المحررات المتعلقة بهذه الوحدات ما لم يقدم صاحب الشأن ما يثبت التزامه بتطبيق أحكام هذه المادة .
ويقع باطلا كل تصرف يخالف ذلك لو كان مسجلا .
وبعد تأجير النسبة المقررة طبقا لهذه المادة يجوز للمالك التصرف فى هذه النسبة كلها أو بعضها وفقا للقواعد العامة .
وفى حالة بيع كامل العقار يلتزم المشترى بأحكام هذه المادة .$m253$,'a2c53a1db02fc792f6ef261c56baf4c5',DATE '1981-07-31',NULL,'active',NULL,NULL,$m253$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 31 تابع (ج) فى 30 يوليه 1981 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m253$),
(14,0,1,$m253$يخصص ثلثا نسبة الـ 15٪ المخصصة للخدمات من أرباح شركات القطاع العام لتمويل الوحدات اللازمة لإسكان العاملين بكل شركة أو مجموعة من الشركات المتجاورة ، ويؤول ما يفيض عن حاجة هؤلاء العاملين إلى صندوق تمويل الإسكان الاقتصادى بالمحافظة .$m253$,'9cb931ff1b1653cff58b1e84c51073bb',DATE '1981-07-31',NULL,'active',NULL,NULL,$m253$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 31 تابع (ج) فى 30 يوليه 1981 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m253$),
(15,0,1,$m253$تكفل الدولة دعم النشاط التعاونى الإسكانى وتوفير ما يلزم له من قروض ومواد للبناء وفقا لأحكام التشريعات المنظمة لهذا النشاط .
كما يكون للأفراد عند تعلية مبانيهم أو استكمالها أو التوسع فيها كما يكون للراغبين فى الاستثمار فى مختلف مستويات الإسكان عدا الفاخر منها ، الحصول على القروض الميسرة التى تقدمها الدولة والهيئات العامة والجهاز المصرفى .
وكل ذلك وفقا للضوابط التى يصدرها قرار من الوزير المختص بالإسكان .$m253$,'52275014c1007f4517b693d09e173da6',DATE '1981-07-31',NULL,'active',NULL,NULL,$m253$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 31 تابع (ج) فى 30 يوليه 1981 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m253$),
(16,0,1,$m253$يحق لمستأجرى المدارس والأقسام الداخلية لإيواء الدارسين بها والمستشفيات وملحقاتهما فى حالة تأجيرها لهم مفروشة الاستمرار فى العين ولو انتهت المدة المتفق عليها وذلك بالشروط وبالأجرة المنصوص عليها فى العقد .$m253$,'5cccff659d52e418d9c2cb76aeb7e28d',DATE '1981-07-31',NULL,'active',NULL,NULL,$m253$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 31 تابع (ج) فى 30 يوليه 1981 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m253$),
(17,0,1,$m253$تنتهى بقوة القانون عقود التأجير لغير المصريين بانتهاء المدد المحددة قانونا لإقامتهم بالبلاد .
بالنسبة للأماكن التى يستأجرها غير المصريين فى تاريخ العمل بأحكام هذا القانون يجوز للمؤجر أن يطلب إخلاءها إذا ما انتهت إقامة المستأجر غير المصرى فى البلاد .
وتثبت إقامة غير المصرى بشهادة من الجهة الإدارية المختصة ويكون إعلان غير المصرى الذى انتهت إقامته قانونا عن طريق النيابة العامة .
ومع ذلك يستمر عقد الإيجار بقوة القانون فى جميع الأحوال لصالح الزوجة المصرية ولأولادها منه الذين كانوا يقيمون بالعين المؤجرة ما لم يثبت مغادرتهم البلاد نهائيا .$m253$,'eb4e78389d78f5f63c28d86f0e13ef0d',DATE '1981-07-31',NULL,'active',NULL,NULL,$m253$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 31 تابع (ج) فى 30 يوليه 1981 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m253$),
(18,0,1,$m253$لا يجوز للمؤجر أن يطلب إخلاء المكان ولو انتهت المدة المتفق عليها فى العقد إلا لأحد الأسباب الآتية :
( أ ) الهدم الكلى أو الجزئى للمنشآت الآيلة للسقوط والإخلاء المؤقت لمقتضيات الترميم والصيانة وفقا للأحكام المنظمة لذلك بالقوانين السارية .
( ب ) إذا لم يقم المستأجر بالوفاء بالأجرة المستحقة خلال خمسة عشر يوما من تاريخ تكليفه بذلك بكتاب موصى عليه مصحوب بعلم الوصول دون مظروف أو بإعلان على يد محضر ولا يحكم بالإخلاء إذا قام المستأجر قبل إقفال باب المرافعة فى الدعوى بأداء الأجرة وكافة ما تكبده المؤجر من مصاريف ونفقات فعلية ،
ولا ينفذ حكم القضاء المستعجل بطرد المستأجر من العين بسبب التأخير فى سداد الأجرة إعمالا للشرط الفاسخ الصريح إذا ما سدد المستأجر الأجرة والمصاريف والأتعاب عند تنفيذ الحكم وبشرط أن يتم التنفيذ فى مواجهة المستأجر .
فإذا تكرر امتناع المستأجر أو تأخره فى الوفاء بالأجرة المستحقة دون مبررات تقدرها المحكمة حكم عليه بالإخلاء أو الطرد بحسب الأحوال .
( ج ) إذا ثبت أن المستأجر قد تنازل عن المكان المؤجر ، أو أجره من الباطن بغير إذن كتابى صريح من المالك للمستأجر الأصلى ، أو تركه للغير بقصد الاستغناء عنه نهائيا وذلك دون إخلال بالحالات التى يجيز فيها القانون للمستأجر تأجير المكان مفروشا أو التنازل عنه أو تأجيره من الباطن أو تركه لذوى القربى وفقا لأحكام المادة 29 من القانون 49 لسنة 1977
( د ) إذا ثبت بحكم قضائى نهائى أن المستأجر استعمل المكان المؤجر أو سمح باستعماله بطريقة مقلقة للراحة أو ضارة بسلامة المبنى أو بالصحة العامة أو فى أغراض منافية للآداب العامة .
ومع عدم الإخلال بالأسباب المشار إليها لا تمتد بقوة القانون عقود إيجار الأماكن المفروشة .
وتلغى المادة ( 31 ) من القانون رقم 49 لسنة 1977 وذلك اعتبارا من تاريخ العمل بهذا القانون .$m253$,'2563042dd2ba785aafd84e69e5fe8ce7',DATE '1981-07-31',NULL,'active',NULL,NULL,$m253$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 31 تابع (ج) فى 30 يوليه 1981 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m253$),
(19,0,1,$m253$فى الأحوال التى يتم فيها تغيير استعمال العين إلى غير أغراض السكنى تزاد الأجرة القانونية بنسبة :
( 1 ) 200٪ للمبانى المنشأة قبل أول يناير 1944 .
( 2 ) 100٪ للمبانى المنشأة منذ أول يناير 1944 وقبل 5 نوفمبر 1961
( 3 ) 75٪ للمبانى المنشأة منذ 5 نوفمبر 1961 وحتى 9 سبتمبر 1977 .
( 4 ) 50٪ للمبانى المنشأة أو التى تنشأ بعد 9 سبتمبر 1977 .
وفى حالة التغيير الجزئى للاستعمال يستحق المالك نصف النسب المشار إليها .
ويشترط ألا يترتب على تغيير الاستعمال كليا أو جزئيا إضرار بالمبنى أو بشاغليه .
وتلغى المادة ( 23 ) من القانون رقم 49 لسنة 1977 وذلك اعتبارا من تاريخ العمل بهذا القانون .$m253$,'a1307b945e5459cf3e494daa3f78034c',DATE '1981-07-31',NULL,'active',NULL,NULL,$m253$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 31 تابع (ج) فى 30 يوليه 1981 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m253$),
(20,0,1,$m253$يحق للمالك عند قيام المستأجر فى الحالات التى يجوز لهم فيها بيع المتجر أو المصنع أو التنازل عن حق الانتفاع بالوحدة السكنية أو المؤجرة لغير أغراض السكنى الحصول على 50٪ من ثمن البيع أو مقابل التنازل بحسب الأحوال ، بعد خصم قيمة المنقولات التى بالعين .
وعلى المستأجر قبل إبرام الاتفاق إعلان المالك على يد محضر بالثمن المعروض ويكون للمالك الحق فى الشراء إذا أبدى رغبته فى ذلك وأودع الثمن مخصوما منه نسبة الـ 50٪ المشار إليها خزانة المحكمة الجزئية الواقع فى دائرتها العقار إيداعا مشروطا بالتنازل عن عقد الإيجار وتسليم العين وذلك خلال شهر من تاريخ الإعلان .
وبانقضاء ذلك الأجل يجوز للمستأجر أن يبيع لغير المالك مع التزام المشترى بأن يؤدى للمالك مباشرة نسبة الـ 50٪ المشار إليها .$m253$,'f3655a35bde8459a25f289f19e0ba2c2',DATE '1981-07-31',NULL,'active',NULL,NULL,$m253$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 31 تابع (ج) فى 30 يوليه 1981 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m253$),
(21,0,1,$m253$يشترط ألا يزيد مجموع ما يقوم المستأجر هو وزوجه وأولاده القصر غير المتزوجين بتأجيره مفروشا - بغير موافقة المالك - على شقة واحدة فى نفس المدينة .
ويمتد فى تحديد المدينة بأحكام قانون الحكم المحلى .$m253$,'09819408b5d7d8d90296ba221849023b',DATE '1981-07-31',NULL,'active',NULL,NULL,$m253$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 31 تابع (ج) فى 30 يوليه 1981 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m253$),
(22,0,1,$m253$تعطى أولوية فى تأجير الوحدات السكنية التى تقيمها الدولة أو المحافظات أو الهيئات العامة أو شركات القطاع العام لتلبية احتياجات العاملين الذين انتهت خدمتهم من شاغلى المساكن التابعة للحكومة ووحدات الحكم المحلى والهيئات العامة وشركات القطاع العام وكذلك ملاك العقارات وأقاربهم حتى الدرجة الثانية فى المحافظة التى يؤجرون بها وحدات العقار المملوك لهم للغير ، وتوزع هذه الوحدات بينهم وفقا للأولويات التى يصدر بها قرار من المحافظ المختص .
وإذا أقام المستأجر مبنى مملوكا له يتكون من أكثر من ثلاث وحدات فى تاريخ لاحق لاستئجاره يكون بالخيار بين الاحتفاظ بسكنه الذى يستأجره أو توفير مكان ملائم لمالكه أو أحد أقاربه حتى الدرجة الثانية بالمبنى الذى أقامه بما لا يجاوز مثلى الأجرة المستحقة له عن الوحدة التى يستأجرها منه .$m253$,'fb55e6dabe3c223e819fc19738d620a8',DATE '1981-07-31',NULL,'active',NULL,NULL,$m253$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 31 تابع (ج) فى 30 يوليه 1981 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m253$),
(23,0,1,$m253$يعاقب بعقوبة جريمة النصب المنصوص عليها فى قانون العقوبات المالك الذى يتقاضى بأية صورة من الصور ، بذاته أو بالوساطة ، أكثر من مقدم عن ذات الوحدة أو يؤجرها لأكثر من مستأجر ، أو يبيعها لغير من تعاقد معه على شرائها ، ويبطل كل تصرف بالبيع لاحق لهذا التاريخ ولو كان مسجلا .
ويعاقب بذات العقوبة المالك الذى يتخلف دون مقتض عن تسليم الوحدة فى الموعد المحدد فضلا عن الزامه بأن يؤدى إلى الطرف الآخر مثلى مقدار المقدم وذلك دون إخلال بالتعاقد ويحق للمستأجر فى استكمال الأعمال الناقصة وفقا لحكم الفقرة الأخيرة من المادة 13 من القانون رقم 49 لسنة 1977 .
ويكون ممثل الشخص الاعتبارى مسئولا عما يقع منه من مخالفات لأحكام هذه المادة .$m253$,'395feab9e5673dddb7288e0aafca2873',DATE '1981-07-31',NULL,'active',NULL,NULL,$m253$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 31 تابع (ج) فى 30 يوليه 1981 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m253$),
(24,0,1,$m253$فيما عدا العقوبة المقررة لجريمة خلو الرجل تلغى جميع العقوبات المقيدة للحرية المنصوص عليها فى القوانين المنظمة لتأجير الأماكن وتنظيم العلاقة بين المؤجر والمستأجر ذلك دون إخلال بأحكام المادة السابقة .
ومع ذلك يعفى من جميع العقوبات المقررة لجريمة خلو الرجل كل من بادر إلى رد ما تقاضاه بالمخالفة لأحكام القانون إلى صاحب الشأن ، وأداء مثليه إلى صندوق تمويل الإسكان الاقتصادى بالمحافظة وذلك قبل أن يصبح الحكم نهائيا فى الدعوى .$m253$,'3ca388b05360ec3110c1b472422b6a5d',DATE '1981-07-31',NULL,'active',NULL,NULL,$m253$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 31 تابع (ج) فى 30 يوليه 1981 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m253$),
(25,0,1,$m253$يقع باطلا بطلانا مطلقا كل شرط أو تعاقد يتم بالمخالفة لأحكام هذا القانون أو القوانين السابقة له المنظمة للعلاقة بين المالك والمستأجر .
وفضلا عن الحكم بالغرامة المنصوص عليها فى هذه القوانين تقضى المحكمة المختصة بإبطال التصرف المخالف واعتباره كأن لم يكن ، ويرد الحالة إلى ما يتفق مع أحكام القانون مع إلزام المخالف بالتعويض إن كان له مقتض .
وفى جميع الأحوال يلزم كل من يحصل على مبالغ بالمخالفة لأحكام تلك القوانين بأن يردها إلى من أداها ، كما يلزم فضلا عن ذلك بدفع مثل هذه المبالغ لصندوق تمويل الإسكان الاقتصادى بالمحافظة .
ويثبت أداء هذه المبالغ بجميع طرق الإثبات .$m253$,'2ed18e4b94008b9051cbe871c40ecb01',DATE '1981-07-31',NULL,'active',NULL,NULL,$m253$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 31 تابع (ج) فى 30 يوليه 1981 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m253$),
(26,0,1,$m253$لا تسرى أحكام المادة ( 9 ) من هذا القانون على الأماكن التى تحتاج إلى ترميم وصيانة بسبب أضرار الحرب ، ويستمر العمل بالقواعد والنظم المطبقة حاليا فى شأن ترميمها وصيانتها .$m253$,'aaed5ddd1400dc94f195852168e3481d',DATE '1981-07-31',NULL,'active',NULL,NULL,$m253$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 31 تابع (ج) فى 30 يوليه 1981 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m253$),
(27,0,1,$m253$تعامل فى تطبيق أحكام هذا القانون معاملة المبانى المؤجرة لأغراض السكنى ، الأماكن المستعملة فى أغراض لا تدخل فى نطاق النشاط التجارى أو الصناعى أو المهنى الخاضع للضريبة على الأرباح التجارية والصناعية أو الضريبة على أرباح المهن غير التجارية .
ولا يفيد من أحكام هذه المادة سوى المستأجرين المصريين .$m253$,'9742d20105a6303a8cfd3019fc165f08',DATE '1981-07-31',NULL,'active',NULL,NULL,$m253$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 31 تابع (ج) فى 30 يوليه 1981 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m253$),
(28,0,1,$m253$تعامل صناديق التأمين الخاصة وصناديق الإسكان معاملة الجمعيات التعاونية لبناء المساكن ، وذلك بالنسبة لما تستثمره هذه الصناديق فى أموال من مجال الإسكان عدا المستوى الفاخر .$m253$,'eee27d7431e3ce90cbd94ddf4446e258',DATE '1981-07-31',NULL,'active',NULL,NULL,$m253$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 31 تابع (ج) فى 30 يوليه 1981 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m253$),
(29,0,1,$m253$ينشر هذا القانون فى الجريدة الرسمية ، ويعمل به من اليوم التالى لتاريخ نشره .$m253$,'ae1ca224d7e2797691b06d55d9fd8f82',DATE '1981-07-31',NULL,'active',NULL,NULL,$m253$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 31 تابع (ج) فى 30 يوليه 1981 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m253$);

DO $m253$
DECLARE
  v_law uuid;
  v_title text;
  v_new_law boolean := false;
  v_ins_art int;
  v_ins_ver int;
  v_cnt int;
  v_vcnt int;
BEGIN
  IF (SELECT count(*) FROM m253_art WHERE md5(body) <> body_md5) <> 0 OR (SELECT count(*) FROM m253_ver WHERE md5(body) <> body_md5) <> 0 THEN
    RAISE EXCEPTION '[253] تلف فى نص أحد الصفوف داخل الملف';
  END IF;
  IF (SELECT count(*) FROM m253_art) <> 30 OR (SELECT sum(char_length(body)) FROM m253_art) <> 15557 OR (SELECT count(*) FROM m253_ver) <> 30 THEN
    RAISE EXCEPTION '[253] عدد الصفوف أو النسخ أو طول النص داخل الملف غير مطابق';
  END IF;

  SELECT id, title INTO v_law, v_title FROM laws WHERE country_code='EG' AND law_no=136 AND law_year=1981 AND kind='law';
  IF v_law IS NOT NULL AND v_title NOT LIKE '%تأجير وبيع الأماكن%' THEN
    RAISE EXCEPTION '[253] يوجد مستند آخر برقم 136 لسنة 1981 (%): لا يُدمج هذا النص فيه', v_title;
  END IF;
  IF v_law IS NULL THEN
    INSERT INTO laws (law_no, law_year, title, short_title, category, status, official_url, enacted_at, last_amended_at, country_code, kind, governance_scope)
    VALUES (136, 1981, $t253$القانون رقم 136 لسنة 1981 فى شأن بعض الأحكام الخاصة بتأجير وبيع الأماكن وتنظيم العلاقة بين المؤجر والمستأجر (النص الأصلى كما نشر بالجريدة الرسمية)$t253$, $t253$قانون الإيجارات 136/1981$t253$, 'other', 'amended', NULL, DATE '1981-07-27', NULL, 'EG', 'law', false)
    RETURNING id INTO v_law;
    v_new_law := true;
  END IF;

  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, body)
  SELECT v_law, article_no, suffix, loc, body FROM m253_art
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING;
  GET DIAGNOSTICS v_ins_art = ROW_COUNT;

  INSERT INTO article_versions (article_id, version_no, body, effective_from, effective_to, status, amended_by_law_no, amended_by_law_year, change_note)
  SELECT a.id, m.version_no, m.body, m.eff, m.eff_to, m.status, m.am_no, m.am_yr, m.note
    FROM articles a JOIN m253_ver m ON m.article_no = a.article_no AND m.suffix = a.article_suffix_order
   WHERE a.law_id = v_law
     AND NOT EXISTS (SELECT 1 FROM article_versions v WHERE v.article_id = a.id)
  ON CONFLICT (article_id, version_no) DO NOTHING;
  GET DIAGNOSTICS v_ins_ver = ROW_COUNT;

  SELECT count(*) INTO v_cnt FROM articles a JOIN m253_art m ON m.article_no=a.article_no AND m.suffix=a.article_suffix_order
   WHERE a.law_id=v_law;
  IF v_cnt <> 30 THEN
    RAISE EXCEPTION '[253] عدد صفوف النص % بدل 30', v_cnt;
  END IF;
  SELECT count(*) INTO v_vcnt FROM article_versions v JOIN articles a ON a.id=v.article_id WHERE a.law_id=v_law;
  IF v_vcnt <> 30 THEN
    RAISE EXCEPTION '[253] عدد نسخ النص % بدل 30', v_vcnt;
  END IF;
  RAISE NOTICE '[253] قانون 136/1981: جديد=%, صفوف مضافة=%, نسخ مضافة=%', v_new_law, v_ins_art, v_ins_ver;
END
$m253$;
